CREATE TABLE "account" (
  "account_id" INTEGER,
  "district_id" INTEGER,
  "frequency" TEXT,
  "date" DATE
);

CREATE TABLE "card" (
  "card_id" INTEGER,
  "disp_id" INTEGER,
  "type" TEXT,
  "issued" DATE
);

CREATE TABLE "disp" (
  "disp_id" INTEGER,
  "client_id" INTEGER,
  "account_id" INTEGER,
  "type" TEXT
);
